	/// <summary><![CDATA[
	/// “我问心无愧，岂能受你要挟……”
	/// ]]></summary>
	Event_SecretInformation_ThreatenFailed_Just,
	/// <summary><![CDATA[
	/// “我不能一错再错，恕难从命……”
	/// ]]></summary>
	Event_SecretInformation_ThreatenFailed_Kind,
	/// <summary><![CDATA[
	/// “仅凭此事便想让我答应，真是痴人说梦……”
	/// ]]></summary>
	Event_SecretInformation_ThreatenFailed_Rebel,
	/// <summary><![CDATA[
	/// “今日之辱，定不敢忘！”
	/// ]]></summary>
	Event_SecretInformation_ThreatenSucceed_Egoistic,
	/// <summary><![CDATA[
	/// “既然如此，此事也该就此了结……”
	/// ]]></summary>
	Event_SecretInformation_ThreatenSucceed_Even,
	/// <summary><![CDATA[
