	Event_SectStoryWudang_TaoYuan,
	/// <summary><![CDATA[
	/// 灿灿如日出流金霞，煌煌若百枝绛点灯
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc1,
	/// <summary><![CDATA[
	/// 澄澄如秋水映明月，清清若疏雨洗芙蓉
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc10,
	/// <summary><![CDATA[
	/// 青青如空山晴滴翠，云霞展呈宝卷天书
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc2,
	/// <summary><![CDATA[
	/// 晴朗如纤云扫秽迹，光明若日月荡杂尘
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc3,
	/// <summary><![CDATA[
	/// 熠熠如乱霞明绮皱，昭昭若初日上金轮
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc4,
	/// <summary><![CDATA[
	/// 灼灼如灯树千光照，灿灿若花焰七枝开
	/// ]]></summary>
	Event_SectStoryWudang_TreasureDesc5,
	/// <summary><![CDATA[
