	/// <summary><![CDATA[
	/// 你想弃我而去，我却也瞧不上你！
	/// ]]></summary>
	Event_Server_Adore_Not_Like_Behavior_4,
	/// <summary><![CDATA[
	/// 终是世态炎凉，日后你我再无干系！
	/// ]]></summary>
	Event_Sever_Adoptive_Relation_Behavior_0,
